// catcher owner app config. ios/ and android/ are generated by prebuild (CNG) and not committed.
// Account-specific values come from the environment, never from this file:
//   EXPO_PUBLIC_EAS_PROJECT_ID — EAS project id (run `eas init` yourself; needed for push tokens)
//   CATCHER_GOOGLE_SERVICES — path to google-services.json for Android push (FCM), gitignored
import type { ExpoConfig } from 'expo/config';
import pkg from './package.json';

const BUNDLE_ID = 'dev.bang9.catcher';

const faceId = 'catcher uses Face ID before it shows your recovery code.';

const config: ExpoConfig = {
  name: 'catcher',
  slug: 'catcher',
  version: pkg.version,
  orientation: 'portrait',
  scheme: 'catcher',
  userInterfaceStyle: 'automatic',
  ios: {
    bundleIdentifier: BUNDLE_ID,
    supportsTablet: false,
    infoPlist: { NSFaceIDUsageDescription: faceId },
  },
  android: {
    package: BUNDLE_ID,
    blockedPermissions: [
      'android.permission.SYSTEM_ALERT_WINDOW',
      'android.permission.READ_EXTERNAL_STORAGE',
      'android.permission.WRITE_EXTERNAL_STORAGE',
    ],
  },
  plugins: [
    'expo-router',
    'expo-sqlite',
    'expo-localization',
    ['expo-secure-store', { faceIDPermission: faceId }],
    ['expo-local-authentication', { faceIDPermission: faceId }],
    ['expo-notifications', { defaultChannel: 'default' }],
    ['expo-splash-screen', { backgroundColor: '#ffffff', dark: { backgroundColor: '#000000' } }],
  ],
  extra: {},
};

const projectId = process.env.EXPO_PUBLIC_EAS_PROJECT_ID;
if (projectId) config.extra = { eas: { projectId } };

const googleServices = process.env.CATCHER_GOOGLE_SERVICES;
if (googleServices && config.android) config.android.googleServicesFile = googleServices;

export default config;
